const std=@import("std");const M=@import("experimental/hydration_mutation_core.zig");
pub fn main()!void{for(0..3)|pair|{for(0..4)|kind|{const n:usize=100000;var checksum:u64=0;var accepted:usize=0;const start=std.time.nanoTimestamp();for(0..n)|i|{var c=M.initialized(i+1);if(kind<2)c.cohorts[0]=.{.biomass=0.4,.support_mass=0.1,.organization=0.25,.lineage=17,.generation=1,.reproduction_credit=0.3};var stats:M.Stats=.{.next_lineage=i+100};std.mem.doNotOptimizeAway(&c);const ok=if(kind%2==0)M.reproduce(&c,0,&c,&stats,true) else M.reproduceWithRetention(&c,0,&c,&stats,true,2027);accepted+=@intFromBool(ok);checksum+%=c.rng;std.mem.doNotOptimizeAway(c);}const elapsed=std.time.nanoTimestamp()-start;std.debug.print("RETENTION_BENCH pair={d} kind={d} n={d} ns_per_attempt={d} accepted={d} legacy_rng_sum={d}\n",.{pair,kind,n,@as(f64,@floatFromInt(elapsed))/n,accepted,checksum});}}}
